import{_ as o,o as t,c as n,a2 as c}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Matrix-Elementwise-Functions.md","filePath":"manual-zh/Matrix-Elementwise-Functions.md","lastUpdated":1785684581000}'),d={name:"manual-zh/Matrix-Elementwise-Functions.md"};function p(r,e,i,s,a,m){return t(),n("div",null,[...e[0]||(e[0]=[c('<h4 id="_16-4-2-1-elementwise-functions" tabindex="-1">16.4.2.1 Elementwise Functions <a class="header-anchor" href="#_16-4-2-1-elementwise-functions" aria-label="Permalink to &quot;16.4.2.1 Elementwise Functions&quot;">​</a></h4><p>这些函数独立地作用于其参数的每个元素，就像逐元素运算符一样（参见 <a href="./Matrix-Elementwise-Binary-Operators">Matrix Elementwise Binary Operators</a>）。</p><p>Matrix Function: <strong>ABS</strong> <em>( M)</em></p><p>取 M 每个元素的绝对值。</p><p><code>ABS({-1, 2; -3, 0}) ⇒ {1, 2; 3, 0}</code></p><p>Matrix Function: <strong>ARSIN</strong> <em>( M)</em> Matrix Function: <strong>ARTAN</strong> <em>( M)</em></p><p>分别计算 M 中每个元素的反正弦或反正切。结果以弧度表示，介于 <em>-\\pi/2</em> 和 <em>+\\pi/2</em> 之间（含）。</p><p><em>\\pi</em> 的值可以计算为 <code>4*ARTAN(1)</code>。</p><p><code>ARSIN({-1, 0, 1}) ⇒ {-1.57, 0, 1.57}</code>（约等于）</p><p><code>ARTAN({-5, -1, 1, 5}) ⇒ {-1.37, -.79, .79, 1.37}</code>（约等于）</p><p>Matrix Function: <strong>COS</strong> <em>( M)</em> Matrix Function: <strong>SIN</strong> <em>( M)</em></p><p>分别计算 M 中每个元素的余弦或正弦，元素必须以弧度表示。</p><p><code>COS({0.785, 1.57; 3.14, 1.57 + 3.14}) ⇒ {.71, 0; -1, 0}</code>（约等于）</p><p>Matrix Function: <strong>EXP</strong> <em>( M)</em></p><p>计算 M 中每个元素 x 的 <em>e^x</em>。</p><p><code>EXP({2, 3; 4, 5}) ⇒ {7.39, 20.09; 54.6, 148.4}</code>（约等于）</p><p>Matrix Function: <strong>LG10</strong> <em>( M)</em> Matrix Function: <strong>LN</strong> <em>( M)</em></p><p>分别计算 M 中每个元素以 10 为底或以 <em>e</em> 为底的对数。</p><p><code>LG10({1, 10, 100, 1000}) ⇒ {0, 1, 2, 3}</code><code>LG10(0) ⇒</code>（错误）</p><p><code>LN({EXP(1), 1, 2, 3, 4}) ⇒ {1, 0, .69, 1.1, 1.39}</code>（约等于） <code>LN(0) ⇒</code>（错误）</p><p>Matrix Function: <strong>MOD</strong> <em>( M, s)</em></p><p>取 M 中每个元素对非零标量值 s 的模，即除以 s 的余数。结果的符号与 dividend（被除数）的符号相同。</p><p><code>MOD({5, 4, 3, 2, 1, 0}, 3) ⇒ {2, 1, 0, 2, 1, 0}</code><code>MOD({5, 4, 3, 2, 1, 0}, -3) ⇒ {2, 1, 0, 2, 1, 0}</code><code>MOD({-5, -4, -3, -2, -1, 0}, 3) ⇒ {-2, -1, 0, -2, -1, 0}</code><code>MOD({-5, -4, -3, -2, -1, 0}, -3) ⇒ {-2, -1, 0, -2, -1, 0}</code><code>MOD({5, 4, 3, 2, 1, 0}, 1.5) ⇒ {.5, 1.0, .0, .5, 1.0, .0}</code><code>MOD({5, 4, 3, 2, 1, 0}, 0) ⇒</code>（错误）</p><p>Matrix Function: <strong>RND</strong> <em>( M)</em> Matrix Function: <strong>TRUNC</strong> <em>( M)</em></p><p>将 M 的每个元素舍入为整数。<code>RND</code> 舍入到最接近的整数，其中 .5 舍入到偶数整数；<code>TRUNC</code> 向零方向舍入。</p><p><code>RND({-1.6, -1.5, -1.4}) ⇒ {-2, -2, -1}</code><code>RND({-.6, -.5, -.4}) ⇒ {-1, 0, 0}</code><code>RND({.4, .5, .6} ⇒ {0, 0, 1}</code><code>RND({1.4, 1.5, 1.6}) ⇒ {1, 2, 2}</code></p><p><code>TRUNC({-1.6, -1.5, -1.4}) ⇒ {-1, -1, -1}</code><code>TRUNC({-.6, -.5, -.4}) ⇒ {0, 0, 0}</code><code>TRUNC({.4, .5, .6} ⇒ {0, 0, 0}</code><code>TRUNC({1.4, 1.5, 1.6}) ⇒ {1, 1, 1}</code></p><p>Matrix Function: <strong>SQRT</strong> <em>( M)</em></p><p>取 M 每个元素的平方根，元素必须非负。</p><p><code>SQRT({0, 1, 2, 4, 9, 81}) ⇒ {0, 1, 1.41, 2, 3, 9}</code>（约等于） <code>SQRT(-1) ⇒</code>（错误）</p>',30)])])}const l=o(d,[["render",p]]);export{u as __pageData,l as default};
